		void SetupContextMenuItems()
		{
			ResetTouchCountMenu = new ZMenuItem(ResString.GetMultilingualString("40bd1ee8-715b-4cfe-83dc-df924720b98c", "Reset Current Touch Count"), ResetFinalisedPickCount_Click);
			Grid.ContextMenu.Popup += delegate
			{
				var selectedElements = Grid.SelectedElements;
				ResetTouchCountMenu.Enabled = (selectedElements.Length != 0 && selectedElements.Cast<WhsLocation>().Any(l => l.WLV_FinalisedPickCount != 0));
			};

			Grid.ContextMenu.MenuItems.Add(ResetTouchCountMenu);
		}

		void ResetFinalisedPickCount_Click(object sender, EventArgs e)
		{
			var selectedLocations = Grid.SelectedElements.Cast<WhsLocation>();

			foreach (var location in selectedLocations.Where(l => l.WLV_FinalisedPickCount != 0))
			{
				location.WLV_FinalisedPickCount = 0;
			}
		}

		#endregion

		#region OnAfterFirstBinding

		protected override void OnAfterFirstBinding(EventArgs e)
		{
			base.OnAfterFirstBinding(e);
			HookEvents();
		}

		void HookEvents()
		{
			var row = Row;
			if (row != null)
			{
				row.SortPickPathMethodInfo.ValueChanged += SortPickPathMethodInfo_ValueChanged;
				row.SortPutawayPathMethodInfo.ValueChanged += SortPutawayPathMethodInfo_ValueChanged;
				row.SortCycleCountMethodInfo.ValueChanged += SortCycleCountMethodInfo_ValueChanged;
				row.NotificationManager.Push(this);
			}
		}

		#region SortPickPathMethodInfo_ValueChanged

		void SortPickPathMethodInfo_ValueChanged(object sender, EventArgs e)
