		#region SetSequenceColumnReadOnly

		void SetSequenceColumnReadOnly(string columnName, string sortPathMethodName)
		{
			var row = Row;
			if (row != null)
			{
				var sortPathMethod = (ZString)row.FindPropertyInfo(sortPathMethodName).Value;
				var sequenceColumnReadOnly = sortPathMethod != CodeLists.SortPathMethods.Codes.UserDefined;
				LocationGrid.Columns[columnName].ColumnStyle.ReadOnly = sequenceColumnReadOnly;
				LocationGrid.Refresh();
			}
		}

		#endregion

