		}

		void UpdateSequenceColumnReadOnly()
		{
			SetSequenceColumnReadOnly(WhsLocationViewSchema.Constants.WLV_PickPathSequence, nameof(WhsRow.SortPickPathMethod));
			SetSequenceColumnReadOnly(WhsLocationViewSchema.Constants.WLV_PutawayPathSequence, nameof(WhsRow.SortPutawayPathMethod));
			if (IsCycleCountEnabled)
			{
				SetSequenceColumnReadOnly(WhsLocationViewSchema.Constants.WLV_CycleCountPathSequence, nameof(WhsRow.SortCycleCountMethod));
			}
		}

		void UpdateControlVisibility()
		{
			var warehouse = Row?.Warehouse;
			if (warehouse != null)
			{
				var isTransitWarehouse = warehouse.WW_WarehouseType.EqualsIgnoringCase(WarehouseTypes.Codes.Transit);
				var isProductOrFtzWarehouse = warehouse.WW_WarehouseType.EqualsIgnoringCase(WarehouseTypes.Codes.Product) || warehouse.WW_WarehouseType.EqualsIgnoringCase(WarehouseTypes.Codes.FreeTradeZone);
				LocationGrid.SetAvailability(isTransitWarehouse, new[]
				{
					WhsLocationViewSchema.Constants.WLV_RS_NKTransitServiceLevel,
					WhsLocationViewSchema.Constants.WLV_TransitDischargeLRC,

					WhsLocationViewSchema.Constants.WLV_MaxDepth,
					WhsLocationViewSchema.Constants.WLV_MaxHeight,
					WhsLocationViewSchema.Constants.WLV_MaxWidth,
					WhsLocationViewSchema.Constants.WLV_MaxDimensionUnit,
				});

				MaxHeightCalcEdit.Visible = isTransitWarehouse;
				MaxDepthCalcEdit.Visible = isTransitWarehouse;
				MaxWidthCalcEdit.Visible = isTransitWarehouse;
				MaxDimensionDropEdit.Visible = isTransitWarehouse;

				if (isTransitWarehouse)
				{
					LocationGrid.SetAvailability(false, new[]
					{
						WhsLocationViewSchema.Constants.WLV_PickMethod,
						WhsLocationViewSchema.Constants.WLV_MaximumPickCountBeforeAutomatedStocktake,
						WhsLocationViewSchema.Constants.WLV_FinalisedPickCount,
						WhsLocationViewSchema.Constants.WLV_LastInventoryChangeDate,
						WhsLocationViewSchema.Constants.WLV_PutawayPathSequence,
						WhsLocationViewSchema.Constants.WLV_MaxQuantity,
						nameof(WhsLocation.RowLocationSequence),
					});

					MaximumTouchCountCalcEdit.Visible = false;
					PickMethodDropEdit.Visible = false;
					MaxQuantityCalcEdit.Visible = false;

					if (IsCycleCountEnabled)
					{
						SortByPathGroupBox.Visible = true;
						PutawayPathSortMethodDropEdit.Visible = false;
						CycleCountSortMethodDropEdit.Location = CargoWise.Windows.UI.ControlDpiScalingHelper.NewScaledPoint(131, 46, true);
					}
					else
					{
						SortByPathGroupBox.Visible = false;
					}

					AdjustControlsWhenTransitWarehouse();
				}

				UpdateControlVisibilityForPalletSpaces(isTransitWarehouse, isProductOrFtzWarehouse);
				UpdateControlVisibilityForCheckDigit(isProductOrFtzWarehouse);
			}
		}

		protected virtual void AdjustControlsWhenTransitWarehouse()
		{
		}

		void UpdateControlVisibilityForCycleCount()
		{
			var warehouse = Row?.Warehouse;
			if (warehouse != null)
			{
				LocationGrid.SetAvailability(IsCycleCountEnabled, [nameof(WhsLocation.WLV_CycleCountLastPerformedForBinding), WhsLocationViewSchema.Constants.WLV_CycleCountPathSequence]);
				CycleCountSortMethodDropEdit.Visible = IsCycleCountEnabled;
			}
		}

		void UpdateControlVisibilityForContainerYardWarehouse()
		{
			if (IsAContainerYardWarehouseRow)
			{
				MaxWeightCalcDropEdit.Visible = false;
				MaxCubicCalcDropEdit.Visible = false;
				PickingAreaGuidFindBox.Visible = false;
				MaximumTouchCountCalcEdit.Visible = false;
				PickMethodDropEdit.Visible = false;

				LocationTypeGuidFindBox.Location = CargoWise.Windows.UI.ControlDpiScalingHelper.NewScaledPoint(123, 22, true);
				StatusDropEdit.Location = CargoWise.Windows.UI.ControlDpiScalingHelper.NewScaledPoint(123, 46, true);
				MaxQuantityCalcEdit.Location = CargoWise.Windows.UI.ControlDpiScalingHelper.NewScaledPoint(123, 70, true);

				LocationGrid.SetAvailability(true, new[]
				{
					WhsLocation.Schema.RowName,
					WhsLocation.Schema.FormattedColumn,
					WhsLocation.Schema.FormattedLevel,
					WhsLocationViewSchema.Constants.WLV_LocationStatus,
					WhsLocationViewSchema.Constants.WLV_WLT_LocationType,
					WhsLocationViewSchema.Constants.WLV_MaxQuantity,
					WhsLocationViewSchema.Constants.WLV_PickPathSequence
				});

				LocationGrid.SetAvailability(false, new[]
				{
					WhsLocation.Schema.FormattedTray,
					WhsLocationViewSchema.Constants.WLV_WA_PickingArea,
					WhsLocationViewSchema.Constants.WLV_PickMethod,
					WhsLocationViewSchema.Constants.WLV_MaxWeight,
					WhsLocationViewSchema.Constants.WLV_MaxWeightUnit,
					WhsLocationViewSchema.Constants.WLV_MaxCubic,
					WhsLocationViewSchema.Constants.WLV_MaxCubicUnit,
					WhsLocationViewSchema.Constants.WLV_MaximumPickCountBeforeAutomatedStocktake,
					WhsLocationViewSchema.Constants.WLV_FinalisedPickCount,
					nameof(WhsLocation.WLV_CycleCountLastPerformedForBinding),
					WhsLocationViewSchema.Constants.WLV_TransitDischargeLRC,
					WhsLocationViewSchema.Constants.WLV_RS_NKTransitServiceLevel,
					WhsLocation.Schema.RowLocationSequence,
				});

				if (ResetTouchCountMenu != null)
				{
					LocationGrid.ContextMenu.MenuItems.Remove(ResetTouchCountMenu);
				}
			}
		}

		void UpdateControlVisibilityForPalletSpaces(bool isTransitWarehouse, bool isProductOrFtzWarehouse)
		{
			var isVisible = isTransitWarehouse || isProductOrFtzWarehouse;
			LocationGrid.SetAvailability(isVisible, new[]
				{
					WhsLocationViewSchema.Constants.WLV_PalletFloorSpaces,
					WhsLocationViewSchema.Constants.WLV_PalletStackHeight,
				});
			PalletFloorSpacesCalcEdit.Visible = isVisible;
			PalletStackHeightCalcEdit.Visible = isVisible;
		}

		void UpdateControlVisibilityForCheckDigit(bool isProductOrFtzWarehouse)
		{
			var isVisible = isProductOrFtzWarehouse;
			LocationGrid.SetAvailability(isVisible, new[]
				{
					WhsLocation.Schema.FormattedCheckDigit,
				});
			GenerateCheckDigitCheckBox.Visible = isVisible;
		}

		MenuItem ResetTouchCountMenu;

		bool IsAContainerYardWarehouseRow
		{
			get
			{
				var warehouse = Row?.Warehouse;
				return warehouse != null && warehouse.WW_WarehouseType == WarehouseTypes.Codes.ContainerYard;
			}
		}

		bool IsCycleCountEnabled
		{
			get
			{
				var isEnabled = false;
				var warehouse = Row?.Warehouse;
				if (warehouse != null)
				{
					isEnabled = warehouse.WW_WarehouseType == WarehouseTypes.Codes.Product
						|| warehouse.WW_WarehouseType == WarehouseTypes.Codes.Transit;
				}

				return isEnabled;
			}
		}
