		#region IRowForm Members

		public List<WhsLocation> SelectedLocations
		{
			get
			{
				List<WhsLocation> result = new List<WhsLocation>();
				for (int i = 0; i < LocationGrid.ListManager.Count; i++)
				{
					if (LocationGrid.IsSelected(i))
					{
						result.Add(Row.Locations[i]);
					}
				}
				return result;
			}
		}

